"""Conversion of legacy OPP_MASTER rows to modern opportunity records."""

from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP


_STAGES: dict[str, tuple[str, int]] = {
    "P": ("prospecting", 10),
    "Q": ("qualified", 25),
    "N": ("negotiation", 60),
    "W": ("closed_won", 100),
    "L": ("closed_lost", 0),
}


def _decimal_or_zero(value: str) -> Decimal:
    """Return a legacy numeric value, treating blank values as zero."""
    if value == "":
        return Decimal(0)
    return Decimal(value)


def _iso_date(value: str) -> str | None:
    """Convert a legacy YYYYMMDD date or sentinel to ISO format."""
    if value in ("", "00000000"):
        return None
    return datetime.strptime(value, "%Y%m%d").date().isoformat()


def _amount_minor(amount: str, currency: str) -> int:
    """Convert a legacy currency amount to rounded integer minor units."""
    exponent = 0 if currency == "JPY" else 2
    scaled = _decimal_or_zero(amount) * (Decimal(10) ** exponent)
    return int(scaled.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def convert_opportunity(row: dict) -> dict | None:
    """Convert one legacy OPP_MASTER row to a modern opportunity record."""
    if row.get("DEL_FLG", "") == "Y":
        return None

    status = row.get("STAT_CD", "")
    try:
        stage, canonical_stage_pct = _STAGES[status]
    except KeyError as exc:
        raise ValueError(f"Unsupported OPP_MASTER STAT_CD: {status!r}") from exc

    currency = row.get("CURR_CD", "") or "USD"
    stage_pct = _decimal_or_zero(row.get("STAGE_PCT", ""))
    flags = (
        ["stage_pct_mismatch"]
        if stage_pct != Decimal(canonical_stage_pct)
        else []
    )

    lost_reason = row.get("LOST_RSN", "") or None

    return {
        "opportunity_id": row.get("OPP_ID", ""),
        "account_id": row.get("ACCT_ID", ""),
        "name": row.get("OPP_NM", ""),
        "stage": stage,
        "amount_minor": _amount_minor(row.get("AMT", ""), currency),
        "currency": currency,
        "close_date": _iso_date(row.get("CLOSE_DT", "")),
        "owner_id": row.get("OWNER_UID", ""),
        "team_code": row.get("TEAM_CD", ""),
        "lost_reason": lost_reason,
        "created_date": _iso_date(row.get("CREATE_DT", "")),
        "updated_date": _iso_date(row.get("UPD_DT", "")),
        "migration_flags": flags,
    }
